<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class PlatformSchema {
    public static function ready(PDO $db):bool{try{return (bool)Db::query($db,'SELECT version FROM migrations WHERE version=?',['003_namira_platform'])->fetchColumn();}catch(\PDOException){return false;}}
    public static function migrate(PDO $db,bool $backup=true):void {
        if(self::ready($db))return;
        $file=Env::storage().'/.platform-upgrade.lock';$lock=fopen($file,'c');if(!$lock)throw new HttpError(503,'قفل ارتقای ساختار در دسترس نیست.');chmod($file,0600);
        if(!flock($lock,LOCK_EX|LOCK_NB)){fclose($lock);throw new HttpError(409,'ارتقای ساختار در پنجره دیگری در جریان است؛ کمی بعد دوباره باز کنید.');}
        try{self::apply($db,$backup);}finally{flock($lock,LOCK_UN);fclose($lock);}
    }
    private static function apply(PDO $db,bool $backup):void {
        if(self::ready($db))return;
        if(!Db::query($db,'SELECT version FROM migrations WHERE version=?',['001_initial'])->fetchColumn())throw new HttpError(503,'پایگاه داده نصب‌شده نامیرا لازم است.');
        $before=DataBackup::counts($db);$snapshot=$backup?DataBackup::create($db,'before-003-platform'):null;
        ProtocolSchema::migrate($db);
        $mysql=$db->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql';$id=$mysql?'INTEGER PRIMARY KEY AUTO_INCREMENT':'INTEGER PRIMARY KEY AUTOINCREMENT';$tail=$mysql?' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci':'';
        $tables=[
            'file_assets'=>"id $id,path VARCHAR(255) NOT NULL,mime VARCHAR(80) NOT NULL,bytes INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,sha256 VARCHAR(64) NOT NULL,created_by INTEGER,created_at VARCHAR(30) NOT NULL",
            'artists'=>"id $id,display_name VARCHAR(255) NOT NULL,slug VARCHAR(150) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'draft',revision INTEGER NOT NULL DEFAULT 0,avatar_asset_id INTEGER,public_avatar_asset_id INTEGER,public_visible INTEGER NOT NULL DEFAULT 0,payload TEXT NOT NULL,public_fields TEXT NOT NULL,public_snapshot TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0,created_by INTEGER,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,FOREIGN KEY(avatar_asset_id) REFERENCES file_assets(id)",
            'artist_terms'=>"artist_id INTEGER NOT NULL,term_id INTEGER NOT NULL,PRIMARY KEY(artist_id,term_id),FOREIGN KEY(artist_id) REFERENCES artists(id),FOREIGN KEY(term_id) REFERENCES protocol_terms(id)",
            'artist_public_terms'=>"artist_id INTEGER NOT NULL,term_id INTEGER NOT NULL,PRIMARY KEY(artist_id,term_id),FOREIGN KEY(artist_id) REFERENCES artists(id),FOREIGN KEY(term_id) REFERENCES protocol_terms(id)",
            'artist_account_claims'=>"id $id,artist_id INTEGER NOT NULL,user_id INTEGER NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',evidence TEXT NOT NULL,reviewed_by INTEGER,review_note TEXT NOT NULL,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,FOREIGN KEY(artist_id) REFERENCES artists(id),FOREIGN KEY(user_id) REFERENCES users(id)",
            'artist_accounts'=>"artist_id INTEGER NOT NULL,user_id INTEGER NOT NULL,verified_by INTEGER NOT NULL,verified_at VARCHAR(30) NOT NULL,PRIMARY KEY(artist_id,user_id),FOREIGN KEY(artist_id) REFERENCES artists(id),FOREIGN KEY(user_id) REFERENCES users(id)",
            'media_details'=>"image_id INTEGER PRIMARY KEY,title VARCHAR(255) NOT NULL,type_id INTEGER,status VARCHAR(30) NOT NULL DEFAULT 'draft',description TEXT NOT NULL,source_text TEXT NOT NULL,rights_text TEXT NOT NULL,download_allowed INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 0,created_by INTEGER,reviewed_by INTEGER,reviewed_at VARCHAR(30),updated_at VARCHAR(30) NOT NULL,FOREIGN KEY(image_id) REFERENCES images(id),FOREIGN KEY(type_id) REFERENCES protocol_terms(id)",
            'media_publication'=>"image_id INTEGER PRIMARY KEY,type_id INTEGER,download_allowed INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,payload TEXT NOT NULL,published_at VARCHAR(30) NOT NULL,FOREIGN KEY(image_id) REFERENCES images(id),FOREIGN KEY(type_id) REFERENCES protocol_terms(id)",
            'media_public_martyrs'=>"image_id INTEGER NOT NULL,martyr_id INTEGER NOT NULL,is_featured INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(image_id,martyr_id),FOREIGN KEY(image_id) REFERENCES images(id),FOREIGN KEY(martyr_id) REFERENCES martyrs(id)",
            'media_public_artists'=>"image_id INTEGER NOT NULL,artist_id INTEGER NOT NULL,creator_role VARCHAR(100) NOT NULL,credit_name VARCHAR(255) NOT NULL,credit_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(image_id,artist_id,creator_role),FOREIGN KEY(image_id) REFERENCES images(id),FOREIGN KEY(artist_id) REFERENCES artists(id)",
            'media_martyrs'=>"image_id INTEGER NOT NULL,martyr_id INTEGER NOT NULL,is_featured INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(image_id,martyr_id),FOREIGN KEY(image_id) REFERENCES images(id),FOREIGN KEY(martyr_id) REFERENCES martyrs(id)",
            'media_artists'=>"image_id INTEGER NOT NULL,artist_id INTEGER NOT NULL,creator_role VARCHAR(100) NOT NULL,credit_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(image_id,artist_id,creator_role),FOREIGN KEY(image_id) REFERENCES images(id),FOREIGN KEY(artist_id) REFERENCES artists(id)",
            'media_changes'=>"id $id,image_id INTEGER NOT NULL,user_id INTEGER,action VARCHAR(80) NOT NULL,before_value TEXT NOT NULL,after_value TEXT NOT NULL,reason TEXT NOT NULL,created_at VARCHAR(30) NOT NULL,FOREIGN KEY(image_id) REFERENCES images(id)",
            'taxonomy_axes'=>"axis_key VARCHAR(40) PRIMARY KEY,title VARCHAR(150) NOT NULL,subject VARCHAR(30) NOT NULL DEFAULT 'martyr',public_filter INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0",
            'roles'=>"role_key VARCHAR(50) PRIMARY KEY,title VARCHAR(150) NOT NULL",
            'role_permissions'=>"role_key VARCHAR(50) NOT NULL,permission VARCHAR(100) NOT NULL,PRIMARY KEY(role_key,permission),FOREIGN KEY(role_key) REFERENCES roles(role_key)",
            'user_roles'=>"user_id INTEGER NOT NULL,role_key VARCHAR(50) NOT NULL,PRIMARY KEY(user_id,role_key),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(role_key) REFERENCES roles(role_key)",
            'design_request_history'=>"id $id,request_id INTEGER NOT NULL,user_id INTEGER,from_status VARCHAR(30) NOT NULL,to_status VARCHAR(30) NOT NULL,note TEXT NOT NULL,created_at VARCHAR(30) NOT NULL,FOREIGN KEY(request_id) REFERENCES design_requests(id)",
            'design_request_details'=>"request_id INTEGER PRIMARY KEY,martyr_id INTEGER,assigned_artist_id INTEGER,assigned_user_id INTEGER,final_image_id INTEGER,publication_consent INTEGER NOT NULL DEFAULT 0,delivered_at VARCHAR(30),revision INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(request_id) REFERENCES design_requests(id),FOREIGN KEY(martyr_id) REFERENCES martyrs(id),FOREIGN KEY(assigned_artist_id) REFERENCES artists(id),FOREIGN KEY(assigned_user_id) REFERENCES users(id),FOREIGN KEY(final_image_id) REFERENCES images(id)",
            'art_calls'=>"id $id,title VARCHAR(255) NOT NULL,slug VARCHAR(150) NOT NULL UNIQUE,description TEXT NOT NULL,terms_text TEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',start_at VARCHAR(30),end_at VARCHAR(30),max_entries INTEGER NOT NULL DEFAULT 5,poster_asset_id INTEGER,criteria TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,created_by INTEGER,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,FOREIGN KEY(poster_asset_id) REFERENCES file_assets(id)",
            'art_submissions'=>"id $id,call_id INTEGER,user_id INTEGER NOT NULL,artist_id INTEGER,martyr_id INTEGER,image_id INTEGER,title VARCHAR(255) NOT NULL,payload TEXT NOT NULL,original_path VARCHAR(255) NOT NULL,mime VARCHAR(80) NOT NULL,sha256 VARCHAR(64) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'submitted',revision INTEGER NOT NULL DEFAULT 0,review_note TEXT NOT NULL,reviewed_by INTEGER,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,FOREIGN KEY(call_id) REFERENCES art_calls(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(artist_id) REFERENCES artists(id),FOREIGN KEY(martyr_id) REFERENCES martyrs(id),FOREIGN KEY(image_id) REFERENCES images(id)",
            'public_contributions'=>"id $id,user_id INTEGER,martyr_id INTEGER,kind VARCHAR(40) NOT NULL,payload TEXT NOT NULL,contact_private TEXT NOT NULL,tracking VARCHAR(64) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'submitted',revision INTEGER NOT NULL DEFAULT 0,reviewed_by INTEGER,review_note TEXT NOT NULL,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(martyr_id) REFERENCES martyrs(id)",
            'contribution_files'=>"id $id,contribution_id INTEGER NOT NULL,path VARCHAR(255) NOT NULL,mime VARCHAR(80) NOT NULL,sha256 VARCHAR(64) NOT NULL,image_id INTEGER,FOREIGN KEY(contribution_id) REFERENCES public_contributions(id),FOREIGN KEY(image_id) REFERENCES images(id)",
            'submission_history'=>"id $id,entity_type VARCHAR(30) NOT NULL,entity_id INTEGER NOT NULL,user_id INTEGER,from_status VARCHAR(30) NOT NULL,to_status VARCHAR(30) NOT NULL,note TEXT NOT NULL,created_at VARCHAR(30) NOT NULL",
            'app_settings'=>"setting_key VARCHAR(100) PRIMARY KEY,value TEXT NOT NULL,updated_by INTEGER,updated_at VARCHAR(30) NOT NULL"
        ];
        foreach($tables as $table=>$cols){if($mysql)$cols=str_replace(' TEXT',' LONGTEXT',$cols);$db->exec("CREATE TABLE IF NOT EXISTS $table ($cols)$tail");}
        foreach(ProtocolSpec::taxonomies()+['art_specialty'=>'رشته هنری','media_type'=>'نوع رسانه'] as $key=>$title)if(!Db::query($db,'SELECT axis_key FROM taxonomy_axes WHERE axis_key=?',[$key])->fetchColumn())Db::insert($db,'taxonomy_axes',['axis_key'=>$key,'title'=>$title,'subject'=>in_array($key,['media_type','art_specialty'],true)?($key==='media_type'?'media':'artist'):'martyr']);
        foreach(['graphic'=>'طراحی گرافیک','illustration'=>'تصویرگری','calligraphy'=>'خوشنویسی','painting'=>'نقاشی','photography'=>'عکاسی','typography'=>'تایپوگرافی','digital'=>'هنر دیجیتال','other'=>'سایر'] as $slug=>$title)self::term($db,'art_specialty',$slug,$title,[]);
        foreach(['portrait'=>'تصویر طراحی‌شده','photo'=>'عکس واقعی شهید','grave'=>'تصویر مزار','family'=>'عکس خانوادگی','handwriting'=>'دست‌نوشته','will'=>'تصویر وصیت‌نامه','document'=>'سند تصویری','other'=>'سایر رسانه‌ها'] as $slug=>$title)self::term($db,'media_type',$slug,$title,['artwork'=>$slug==='portrait']);
        foreach(['superadmin'=>'مدیر کل','content'=>'کارشناس بانک شهدا','shop'=>'مدیر فروشگاه','media_manager'=>'مدیر رسانه','reviewer'=>'بازبین آثار','call_manager'=>'مدیر فراخوان','contribution_manager'=>'مسئول مشارکت','design_manager'=>'مسئول طراحی','artist'=>'هنرمند','member'=>'کاربر'] as $role=>$title)if(!Db::query($db,'SELECT role_key FROM roles WHERE role_key=?',[$role])->fetchColumn())Db::insert($db,'roles',['role_key'=>$role,'title'=>$title]);
        foreach(Permissions::defaults() as $role=>$permissions)foreach($permissions as $permission)if(!Db::query($db,'SELECT permission FROM role_permissions WHERE role_key=? AND permission=?',[$role,$permission])->fetchColumn())Db::insert($db,'role_permissions',['role_key'=>$role,'permission'=>$permission]);
        foreach(Db::query($db,'SELECT id,role FROM users')->fetchAll() as $user)if(Db::query($db,'SELECT role_key FROM roles WHERE role_key=?',[$user['role']])->fetchColumn()&&!Db::query($db,'SELECT user_id FROM user_roles WHERE user_id=? AND role_key=?',[$user['id'],$user['role']])->fetchColumn())Db::insert($db,'user_roles',['user_id'=>$user['id'],'role_key'=>$user['role']]);
        $portrait=self::termId($db,'media_type','portrait');$photo=self::termId($db,'media_type','photo');$document=self::termId($db,'media_type','document');
        $typeCase="CASE i.kind WHEN 'photo' THEN $photo WHEN 'document' THEN $document ELSE $portrait END";
        Db::query($db,"INSERT INTO media_details(image_id,title,type_id,status,description,source_text,rights_text,download_allowed,sort_order,revision,updated_at) SELECT i.id,i.title,$typeCase,CASE WHEN i.published=1 THEN 'published' ELSE 'draft' END,'','',i.license_text,1,0,0,? FROM images i WHERE NOT EXISTS(SELECT 1 FROM media_details d WHERE d.image_id=i.id)",[date('Y-m-d H:i:s')]);
        $db->exec("INSERT INTO media_martyrs(image_id,martyr_id,is_featured) SELECT i.id,i.martyr_id,0 FROM images i WHERE NOT EXISTS(SELECT 1 FROM media_martyrs mm WHERE mm.image_id=i.id AND mm.martyr_id=i.martyr_id)");
        $db->exec("INSERT INTO media_publication(image_id,type_id,download_allowed,sort_order,payload,published_at) SELECT i.id,$typeCase,1,0,JSON_OBJECT('description','','source_text','','rights_text',i.license_text),i.created_at FROM images i WHERE i.published=1 AND NOT EXISTS(SELECT 1 FROM media_publication mp WHERE mp.image_id=i.id)");
        $db->exec("INSERT INTO media_public_martyrs(image_id,martyr_id,is_featured) SELECT i.id,i.martyr_id,0 FROM images i WHERE i.published=1 AND NOT EXISTS(SELECT 1 FROM media_public_martyrs mm WHERE mm.image_id=i.id AND mm.martyr_id=i.martyr_id)");
        foreach(['media_status'=>'media_details(status,type_id)','media_artist'=>'media_artists(artist_id,image_id)','media_person'=>'media_martyrs(martyr_id,image_id)','media_public_person'=>'media_public_martyrs(martyr_id,image_id)','media_public_artist'=>'media_public_artists(artist_id,image_id)','artists_public'=>'artists(status,archived)','submissions_queue'=>'art_submissions(status,created_at)','contributions_queue'=>'public_contributions(status,created_at)'] as $name=>$cols)try{$db->exec("CREATE INDEX $name ON $cols");}catch(\PDOException $e){if(!str_contains($e->getMessage(),'already exists')&&(int)($e->errorInfo[1]??0)!==1061)throw $e;}
        DataBackup::verifyCounts($db,$before);
        Db::insert($db,'migrations',['version'=>'003_namira_platform','applied_at'=>date('Y-m-d H:i:s')]);
        Db::audit($db,'migration.003',$snapshot['name']??'fixture-no-backup');
    }
    private static function term(PDO $db,string $taxonomy,string $slug,string $title,array $meta):void{if(!Db::query($db,'SELECT id FROM protocol_terms WHERE taxonomy=? AND slug=?',[$taxonomy,$slug])->fetchColumn())Db::insert($db,'protocol_terms',['taxonomy'=>$taxonomy,'slug'=>$slug,'title'=>$title,'aliases'=>'[]','metadata'=>Protocol::encode($meta)]);}
    public static function termId(PDO $db,string $taxonomy,string $slug):int{return (int)Db::query($db,'SELECT id FROM protocol_terms WHERE taxonomy=? AND slug=?',[$taxonomy,$slug])->fetchColumn();}
}
